import jax; import jax.numpy as jnp; from jax import jit, vmap, lax; import flax.linen as nn; from ray import tune; import optax; from typing import Tuple, Optional, Dict, Any
# --- SELF-CONTAINED SUBMISSION ---
class ConvLSTMCellLN(nn.Module):
    features: int; @nn.compact
    def __call__(self, carry, x): h,c=carry; gates=nn.Conv(4*self.features,(3,3),padding='SAME')(jnp.concatenate([x,h],axis=-1)); gates=nn.LayerNorm(epsilon=1e-5)(gates); i,f,g,o=jnp.split(gates,4,axis=-1); i,f,o=nn.sigmoid(i),nn.sigmoid(f),nn.sigmoid(o); g=jnp.tanh(g); c=f*c+i*g; h=o*jnp.tanh(c); return (h,c),h
class BottleneckBlock(nn.Module):
    features: int; @nn.compact
    def __call__(self, x): y=nn.Conv(self.features//4,(1,1))(x); y=nn.relu(y); y=nn.Conv(self.features//4,(3,3),padding='SAME')(y); y=nn.relu(y); y=nn.Conv(self.features,(1,1))(y); return nn.relu(x+y)

class KronoNetV4_NoNorm(nn.Module):
    cnn_features_1:int; cnn_features_2:int; conv_lstm_features:int; dilation_rate:int; num_heads:int=2; steps:int=2
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        B,H,W,_=x.shape; cnn_out=nn.Conv(self.cnn_features_1,(3,3),padding='SAME',kernel_dilation=self.dilation_rate)(x); cnn_out=nn.relu(cnn_out); cnn_out=BottleneckBlock(self.cnn_features_1)(cnn_out); cnn_out=nn.Conv(self.cnn_features_2,(3,3),padding='SAME',kernel_dilation=self.dilation_rate)(cnn_out); cnn_out=nn.relu(cnn_out); cnn_out=BottleneckBlock(self.cnn_features_2)(cnn_out);
        if rnn_state is None: rnn_state = (jnp.zeros((B,H,W,self.conv_lstm_features)), jnp.zeros((B,H,W,self.conv_lstm_features)))
        if done is not None: m=(1.0-done.reshape(B,1,1,1)); rnn_state=jax.tree.map(lambda y:y*m, rnn_state)
        h,c=rnn_state; lstm_cell=ConvLSTMCellLN(self.conv_lstm_features)
        for _ in range(self.steps): (h,c),h_out = lstm_cell((h,c),cnn_out)
        new_rnn_state=(h,c); attn_logits=nn.Conv(self.num_heads,(1,1),padding='SAME')(h_out); attn_logits_reshaped=attn_logits.reshape(B,H*W,self.num_heads); attn_weights=nn.softmax(attn_logits_reshaped,axis=1); attn_weights=attn_weights.reshape(B,H,W,self.num_heads); z_heads=jnp.einsum('bhwc,bhwn->bnc',h_out,attn_weights); z=z_heads.reshape((B,-1));
        z=nn.Dense(256)(z); z=nn.relu(z); policy_logits=nn.Dense(4)(z); value=nn.Dense(1)(z).squeeze(-1); return policy_logits,value,new_rnn_state

# ===== CAUSAL PPO training step =====
def causal_ppo_training_step(network,optimizer,params,opt_state,batch,hparams):
    obs,acts,rews,dones=batch['observations'],batch['actions'],batch['rewards'],batch['dones']; old_vals,old_logs=batch['values'],batch['log_probs']; final_vals,rnn_states=batch['final_values'],batch.get('initial_rnn_states',None); rews=rews-(rews==-1.0)*hparams.get('mistake_penalty',1.0);
    v_tp1=jnp.concatenate([old_vals[:,1:],final_vals[:,None]],axis=1); mask=(1.0-dones.astype(jnp.float32)); deltas=rews+0.97*v_tp1*mask-old_vals
    def scan_fn(adv,t): adv=deltas[:,t]+0.97*hparams.get('gae_lambda',0.97)*mask[:,t]*adv; return adv,adv
    _,advs=lax.scan(scan_fn,jnp.zeros(obs.shape[0]),jnp.arange(obs.shape[1]-1,-1,-1)); advs=advs[::-1].T; returns=advs+old_vals; B,T=obs.shape[:2]

    def get_all_outputs(params):
        def process_env(idx):
            rnn_state = jax.tree.map(lambda x: lax.stop_gradient(x[idx]), rnn_states)
            def step(carry,t):
                logits,val,rnn = network.apply(params,obs[idx,t][None,...], jnp.where(t>0,dones[idx,t-1],False)[None,...], jax.tree.map(lambda x:x[None,...],carry))
                return jax.tree.map(lambda x:x[0],rnn), (logits[0],val[0])
            _,(logits,values) = lax.scan(step,rnn_state,jnp.arange(T)); return logits,values
        return vmap(process_env)(jnp.arange(B))

    def policy_loss_fn(params):
        all_logits, _ = get_all_outputs(params)
        logs=nn.log_softmax(all_logits,axis=-1); new_logs=logs[jnp.arange(B)[:,None],jnp.arange(T),acts]; ratio=jnp.exp(new_logs-old_logs); adv=lax.stop_gradient(advs)
        ploss = -jnp.mean(jnp.minimum(ratio*adv,jnp.clip(ratio,1-hparams['clip_epsilon'],1+hparams['clip_epsilon'])*adv))
        ent = -jnp.mean(jnp.sum(nn.softmax(all_logits,axis=-1)*logs,axis=-1))
        return ploss - hparams['entropy_coef']*ent

    def value_loss_fn(params):
        _, all_values = get_all_outputs(params)
        return 0.5*jnp.mean((all_values-lax.stop_gradient(returns))**2)

    p_grads = jax.grad(policy_loss_fn)(params); v_grads = jax.grad(value_loss_fn)(params)
    beta = hparams['beta']
    combined_grads = jax.tree_util.tree_map(lambda pg, vg: pg + beta * vg, p_grads, v_grads)
    updates,opt_state=optimizer.update(combined_grads,opt_state,params); return optax.apply_updates(params,updates),opt_state

def _define_hyperparameters():
    return {'learning_rate':tune.choice([4e-4]), 'entropy_coef':tune.choice([0.01]), 'cnn_features_1':tune.choice([32]), 'cnn_features_2':tune.choice([64]), 'conv_lstm_features':tune.choice([96]), 'dilation_rate':tune.choice([6]), 'clip_epsilon':tune.choice([0.2]), 'mistake_penalty':tune.choice([1.0]), 'gae_lambda':tune.choice([0.97]), 'num_heads':tune.choice([2]), 'steps':tune.choice([2]), 'beta':tune.choice([0.2, 0.5, 1.0])}
def create_network(hparams):
    return KronoNetV4_NoNorm(**{k:hparams[k] for k in ['cnn_features_1','cnn_features_2','conv_lstm_features','dilation_rate','num_heads','steps']})
training_step = causal_ppo_training_step
def create_optimizer(learning_rate:float=4e-4):
    return optax.chain(optax.clip_by_global_norm(1.0),optax.adamw(learning_rate,weight_decay=1e-4))
